css:
.receipt-box {
   max-width: 700px;
   margin: auto;
   padding: 30px;
   border: 1px solid #ccc;
   font-family: 'Helvetica', 'Arial', sans-serif;
   font-size: 14px;
   color: #333;
 }
 .title {
   font-size: 22px;
   font-weight: bold;
   margin-bottom: 20px;
   color: #222;
 }
 .section {
   margin-top: 20px;
 }
 .section h3 {
   font-size: 16px;
   margin-bottom: 10px;
   border-bottom: 1px solid #ddd;
   padding-bottom: 5px;
 }
 table {
   width: 100%;
 }
 td {
   padding: 6px 4px;
 }
